UPDATE `interview_question` SET `content` = '假设现在让你基于Function calling制作一个天气查询的功能, 后端代码如何写?', `reference_answer` = '基于Function calling做天气查询的后端核心逻辑分4步：\n1. 定义函数描述：定义天气查询函数的入参（城市、日期）、出参（温度、天气状况）\n2. 调用大模型：把用户提问 + 函数描述传给大模型，让模型判断是否需要调用天气函数，并返回标准化的调用参数\n3. 执行本地函数：解析大模型返回的调用参数，调用真实的天气 API（可以对接高德）获取数据\n4. 结果回填：把天气数据传给大模型，让模型生成自然语言回答，返回给用户' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 15 AND LEFT(`content`, 20) = '假设现在让你基于Function cal' AND `delete_flag` = 0;
