UPDATE `interview_question` SET `content` = '如果错误发生在LangGraph工作流的中间步骤（比如调用高德地图 API 失败），如何利用Checkpoint机制实现“断点续传”或“状态回滚”？', `reference_answer` = 'LangGraph 的 Checkpoint 机制本质是持久化工作流的状态快照，包含：\n1. 工作流当前执行到的节点\n2. 所有已完成步骤的状态数据\n3. 对话 / 工作流的上下文信息实现 “断点续传” 和 “状态回滚” 的核心逻辑是：\n- 断点续传：出错时保存当前最新的有效 Checkpoint，恢复时从该 Checkpoint 加载状态，跳过已成功执行的步骤，直接从出错节点重新执行。\n- 状态回滚：出错时放弃当前错误状态，加载上一个成功步骤的 Checkpoint，回到出错前的状态，可选择重试该步骤或调整逻辑后重新执行。' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 30 AND LEFT(`content`, 20) = '如果错误发生在LangGraph工作流的' AND `delete_flag` = 0;
UPDATE `interview_question` SET `delete_flag` = 1 WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` IN (31) AND `content` IN ('败），如何利用Checkpoint机制实现“断点续传”或“状态回滚”？') AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '当使用fastapi承载大模型接口时，你是如何处理那些可能阻塞事件循环的操作的？比如涉及到外部io模型推理或者耗时的数据处理时？你采取过哪些方式来避免阻塞主事件循环？', `reference_answer` = 'FastAPI 基于异步的 Starlette 框架，其高性能依赖于非阻塞的事件循环。一旦有同步阻塞操作（如 CPU 密集型计算、无异步接口的外部 IO 调用）占用事件循环，会导致整个服务的并发能力急剧下降。\n解决思路分为三类：\n1. 异步化改造：优先使用异步库替代同步库，让 IO 操作让出事件循环。\n2. 线程 / 进程池隔离：将阻塞操作放到独立的线程 / 进程池中执行，避免占用主事件循环。\n3. 服务拆分：将重度阻塞的操作（如大模型推理）拆分为独立服务，通过消息队列异步调用。' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 32 AND LEFT(`content`, 20) = '当使用fastapi承载大模型接口时，你' AND `delete_flag` = 0;
UPDATE `interview_question` SET `delete_flag` = 1 WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` IN (33,34) AND `content` IN ('作的？比如涉及到外部io模型推理或者耗时的数据处理时？你采取过哪些方式','来避免阻塞主事件循环？') AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '构建智能体流程的过程中，当系统需要连续经过多个节点才能得到最终结果时，你是如何确保用户能够尽快看到内容的？比如在请求还没完全结束之前，系统是否会提前输出部分结果？或者采取其他方式来提升游戏体验，请结合你当时的实际做法来讲一讲？', `reference_answer` = '在构建智能体流程时，我主要从三个方面保障用户体验：流式输出、分阶段反馈、并行处理与降级策略。\n应。当大模型开始生成 token 时，我们就以小数据块的形式逐个返回，用户可以立刻看到‘打字机’ 第二，分阶段输出中间结果。对于多步骤任务（如‘检索 → 分析 → 总结’），我们不会等到全部完成才返回。例如，在检索阶段完成后，先返回‘正在分析文档…’这类友好提示；分析完成后，再展示初步结论。这样用户始终知道系统在做什么。\n第三，关键任务并行化(异步)。如果多个子任务是独立的（如同时调用天气 API 和交通 API），我们会并行执行，并采用‘谁先完成先展示’的策略，提升整体感知速度。\n第四，设置降级策略兜底。若某环节超时未完成，我们返回简化版答案或默认提示（如‘信息获取中，请稍后重试’），防止用户卡死。' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 35 AND LEFT(`content`, 20) = '构建智能体流程的过程中，当系统需要连续经' AND `delete_flag` = 0;
UPDATE `interview_question` SET `delete_flag` = 1 WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` IN (36,37,38) AND `content` IN ('时，你是如何确保用户能够尽快看到内容的？比如在请求还没完全结束之','前，系统是否会提前输出部分结果？或者采取其他方式来提升游戏体验，请','结合你当时的实际做法来讲一讲') AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '调用智能体（Agent）出错时（如 API 超时、异常），你们的系统如何做错误兜底和降级处理？', `reference_answer` = '节点内使用异常处理, 如果工具调用出错会返回友好提示, 比如关键步骤出错会返回"xx功能暂不可用", 对于非核心功能我们会直接熔断只保证核心功能可用, 同时我们会记录日志到监控系统便于之后查看修复如后续追问日志怎么用的: 我们公司做了一个可复用的, 带文件和控制台输出的log文件, 它用的是Python内置的日志模块, 并且读取了我们的配置, 它一般只记录INFO以上级别的日志, 开发时我们才临时调成DEBUG, 它可以同时输出日志到磁盘以及开发时实时查看控制台输出' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 39 AND LEFT(`content`, 20) = '调用智能体（Agent）出错时（如 AP' AND `delete_flag` = 0;
