UPDATE `interview_question` SET `content` = '什么是“意图-动作状态机”，并说明它在对话系统中的作用。结合大模型（LLM），你是如何实现这种状态机的？', `reference_answer` = '意图-动作状态机’是一种用于管理任务型对话流程的设计模式，其核心思想是：\n将整个对话拆分为若干明确的状态（如‘询问出发地’、‘确认订单’），每个状态对应一个用户意图阶段。当用户输入新消息后，系统根据当前状态 + 用户内容，决定：\n- 下一步进入哪个状态\n- 执行什么动作（如追问信息、调用工具、结束对话）\n一共解决了三个问题\n1. 保证流程可控：按业务规则一步步走，避免遗漏关键信息；\n2. 提升成功率：在预设路径上引导用户，减少幻觉或无效回复；\n3. 便于维护和测试：每个状态逻辑独立，新增/修改不影响整体在实际项目中，我们使用 LangGraph 来实现这种状态机：\n- 支持循环（如多次追问）、异常处理（fallback）' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 41 AND LEFT(`content`, 20) = '什么是“意图-动作状态机”，并说明它在对' AND `delete_flag` = 0;
