UPDATE `interview_question` SET `content` = '如果你做的一项工作受到上级领导的表扬，但你主管领导却说是他做的，你该怎样？', `reference_answer` = '回答提示：我首先不会找那位上级领导说明这件事，我会主动找我的主管领导来沟通，因为沟通是解决人际关系的最好办法，但结果会有两种：\n①我的主管领导认识到自己的错误，我想我会视具体情况决定是否原谅他。\n②他更加变本加厉的来威胁我，那我会毫不犹豫地找我的上级领导反映此事，因为他这样做会造成负面影响，对今后的工作不利。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 212 AND LEFT(`content`, 20) = '如果你做的一项工作受到上级领导的表扬，但' AND `delete_flag` = 0;
