UPDATE `interview_question` SET `content` = '假设你在某单位工作，成绩比较突出，得到领导的肯定。但同时你发现同事们越来越孤立你，你怎么看这个问题？你准备怎么办？', `reference_answer` = '回答提示：\n①成绩比较突出，得到领导的肯定是件好事情，以后更加努力。\n②检讨一下自己是不是对工作的热心度超过同事间交往的热心了，加强同事间的交往及共同的兴趣爱好。\n③工作中，切勿伤害别人的自尊心。\n④不在领导前拨弄是非。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 214 AND LEFT(`content`, 20) = '假设你在某单位工作，成绩比较突出，得到领' AND `delete_flag` = 0;
