UPDATE `interview_question` SET `content` = '在完成某项工作时，你认为领导要求的方式不是最好的，自己还有更好的方法，你应该怎么做？', `reference_answer` = '回答提示：\n①.原则上我会尊重和服从领导的工作安排，同时私底下找机会以请教的口吻，婉转地表达自己的想法，看看领导是否能改变想法。\n②如果领导没有采纳我的建议，我也同样会按领导的要求认真地去完成这项工作。毕竟，领导所站的角度和眼光跟作为员工的我来说还是不一样的，有可能他考虑的更加全面。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 217 AND LEFT(`content`, 20) = '在完成某项工作时，你认为领导要求的方式不' AND `delete_flag` = 0;
