UPDATE `interview_question` SET `content` = '我们现在的项目与你之前的项目还是有很多区别的，你如何能胜任这项工作？', `reference_answer` = '回答提示：其实工作中遇到困难在所难免，以前做项目的时候也不是所有的都熟悉和了解，遇到没有接触过的问题，一方面请教经验更为丰富的同事，另一方面，现在互联网这么发达，各种学习资料都可以找的到，我还可以利用业余时间充电学习。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 232 AND LEFT(`content`, 20) = '我们现在的项目与你之前的项目还是有很多区' AND `delete_flag` = 0;
