UPDATE `interview_question` SET `content` = '你们的 Ollama 用的什么模型版本？', `reference_answer` = '我们开发联调环境用 Ollama 部署 qwen2.5:7b 和 qwen2.5:14b，生产推理用 qwen2.5:32b 的量化版本；具体版本以 `ollama list` 输出为准。选型时主要看显存占用、首 token 延迟和中文效果，版本升级前会先在评测集上做回归。' WHERE `source_doc_name` = 'AI面试题.md' AND `source_seq` = 28 AND `content` = '你们的Ollama用的什么模型版本？' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '说一说 Tool Calling 调用原理？', `reference_answer` = 'Tool Calling（Function Calling）的原理是：应用把可用工具的名称、说明和参数 JSON Schema 随请求一起发给模型；模型根据用户意图判断是否需要调用工具，并输出结构化的工具名和参数；应用侧校验参数、执行真实函数，再把执行结果作为工具消息回填到上下文；模型基于工具结果继续生成最终回答或发起下一次调用。整个过程模型只负责“决策和生成参数”，真正的工具执行、权限校验、超时重试和幂等由应用侧完成。' WHERE `source_doc_name` = 'AI面试题.md' AND `source_seq` = 69 AND `content` = '说一说Toolcalling调用原理' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '做 AI 项目的时候，遇到了哪些问题，如何解决的？', `reference_answer` = '常见问题主要有四类：① RAG 召回不准或答非所问，通过查询改写、混合检索、重排和父子块切分解决；② 多轮对话上下文丢失或串话，用会话 ID 隔离、Redis 持久化记忆和上下文摘要解决；③ 流式输出被前端中断后消息未落库，用服务端完成回调 + 状态补偿解决；④ 大模型输出不稳定、格式不合法，用结构化输出、JSON 校验、失败重试和规则兜底解决。另外还会做超时、熔断、限流和日志监控，避免单个模型调用拖垮整个链路。' WHERE `source_doc_name` = 'AI面试题.md' AND `source_seq` = 78 AND `content` = '做AI项目的时候，遇到了哪些问题，如何解决的' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '常见的 HTTP 响应状态码有哪些？', `reference_answer` = '按类别分：1xx 信息类（100 Continue、101 Switching Protocols）；2xx 成功（200 OK、201 Created、204 No Content）；3xx 重定向（301 永久重定向、302 临时重定向、304 Not Modified）；4xx 客户端错误（400 Bad Request、401 Unauthorized、403 Forbidden、404 Not Found、405 Method Not Allowed、409 Conflict、429 Too Many Requests）；5xx 服务端错误（500 Internal Server Error、502 Bad Gateway、503 Service Unavailable、504 Gateway Timeout）。实际接口设计里，业务错误通常仍返回 200，用统一响应体的 code 区分；认证失败用 401，权限不足用 403，限流用 429。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 37 AND `content` = '常见的HTP响应状态码' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = 'Spring Cloud 组件分类有哪几类？', `reference_answer` = '一般分为：① 注册与配置中心（Eureka、Nacos、Consul、Config）；② 服务调用与负载均衡（OpenFeign、LoadBalancer、Ribbon）；③ 网关（Spring Cloud Gateway、Zuul）；④ 熔断限流与容错（Sentinel、Resilience4j、Hystrix）；⑤ 链路追踪与监控（Sleuth、Micrometer、Zipkin、SkyWalking）；⑥ 消息与事件（Spring Cloud Stream、Bus）；⑦ 安全（Spring Cloud Security、OAuth2）。实际项目不一定全部使用，比如 Nacos 可以同时承担注册中心和配置中心。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 90 AND `content` = 'SpringCloud组件分类哪几类？' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '百度云接口收费多少钱？', `reference_answer` = '百度智能云的接口大多按调用量或资源包计费，OCR、语音识别、自然语言处理等不同产品单价不同，也有免费额度和按 QPS 扩容的阶梯价格。我们只在营业执照/身份证 OCR 等必要场景调用，并做了结果缓存、调用量限额和失败重试，具体价格以官网实时报价和商务合同为准。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 190 AND `content` = '百度云接口收费多少钱' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '问题12：Java 中 3*0.1 == 0.3 将会返回什么？怎么比较才能为 true？', `reference_answer` = '返回 false。因为 0.1、0.3 这类十进制小数无法用二进制浮点数精确表示，3*0.1 的实际结果约为 0.30000000000000004，和 0.3 的字面量表示不相等。精确比较应使用 BigDecimal（用字符串构造，如 new BigDecimal("0.1").multiply(new BigDecimal("3")).compareTo(new BigDecimal("0.3")) == 0）；如果坚持用 double，可以按误差范围比较，如 Math.abs(a - b) < 1e-9。' WHERE `source_doc_name` = 'Java面试.md' AND `source_seq` = 290 AND `content` = '问题12：Java中3*0.1 == 0.3 将会返回什么？怎么比较才能为true' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '主流向量数据库的适合场景及优缺点？', `reference_answer` = '常见的有 Milvus、Qdrant、Weaviate、Pinecone、Chroma、pgvector 和 FAISS。Milvus 适合大规模、高并发的生产检索，索引类型丰富，但部署和运维成本较高；Qdrant 轻量、过滤能力强、Rust 实现性能好，适合中小规模和中台场景；Weaviate 自带混合检索和模块化能力，生态完善但资源占用偏高；Pinecone 是全托管服务，免运维、弹性好，但成本高且数据在云端；Chroma 适合本地原型和小规模应用，简单易用但生产级能力有限；pgvector 适合已经使用 PostgreSQL、数据量中等的场景，事务和过滤方便，但超大规模性能不如专用向量库；FAISS 是检索库而非数据库，性能高、灵活，但需要自己实现持久化、增删和权限。选型主要看数据规模、过滤需求、部署方式和运维成本。' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 7 AND `content` = '主流向量数据库的适合场景及优缺点' AND `delete_flag` = 0;
UPDATE `interview_question` SET `content` = '你知道 Milvus 数据库支持哪些索引吗？', `reference_answer` = 'Milvus 支持 FLAT（暴力检索，精度最高、适合小数据量）、IVF_FLAT、IVF_SQ8、IVF_PQ（倒排 + 量化，适合大规模、内存敏感场景）、HNSW（图索引，查询快、召回高，但内存占用较大）、DISKANN（磁盘索引，适合超大规模、低成本场景）、SCANN，以及 GPU_IVF_FLAT、GPU_IVF_PQ、GPU_CAGRA 等 GPU 索引。选择时在召回率、延迟、内存和构建时间之间权衡：小数据量用 FLAT，大规模在线检索常用 HNSW 或 IVF 系列，超大规模且内存有限可以用 DISKANN。' WHERE `source_doc_name` = 'Python+AI面试题.md' AND `source_seq` = 10 AND `content` = '你知道Milvus数据库支持哪些索引吗？' AND `delete_flag` = 0;

COMMIT;
